 namespace ReadyToMigrate.Services;

 public class CouponService
 {
     private readonly ILogger<CouponService> _logger;
     private readonly TimeProvider _timeProvider;

     public CouponService(ILogger<CouponService> logger, TimeProvider timeProvider)
     {
         _logger = logger;
         _timeProvider = timeProvider;
     }

     public Coupon CreateCoupon(string code, int validDays)
     {
         return new Coupon
         {
             Code = code,
             CreatedAt = _timeProvider.GetUtcNow().DateTime,
             ExpiresAt = _timeProvider.GetUtcNow().AddDays(validDays).DateTime
         };
     }

     public bool IsValid(Coupon coupon)
     {
         if (_timeProvider.GetUtcNow().DateTime > coupon.ExpiresAt)
         {
             _logger.LogInformation("Coupon {Code} expired at {Expiry}", coupon.Code, coupon.ExpiresAt);
             return false;
         }
         return true;
     }

     public bool IsRedeemableToday(Coupon coupon)
     {
         // Uses the storefront's LOCAL calendar day on purpose — a coupon that
         // expires today should still redeem regardless of UTC offset.
         return coupon.ExpiresAt.Date >= _timeProvider.GetLocalNow().DateTime.Date;
     }

     public TimeSpan TimeUntilExpiry(Coupon coupon)
     {
         var remaining = coupon.ExpiresAt - _timeProvider.GetUtcNow().DateTime;
         return remaining > TimeSpan.Zero ? remaining : TimeSpan.Zero;
     }
 }

